WITH cleaned AS (SELECT *, COALESCE(location, 'Unknown') AS location_filled, COALESCE(dept_name, 'DIRECT') AS dept_name_filled FROM departments WHERE budget > 1578000) SELECT id, dept_name, location_filled, MAX(budget) OVER (PARTITION BY dept_name, location ORDER BY budget, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_max_budget, SUM(budget) OVER (PARTITION BY dept_name, location ORDER BY budget, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_sum_budget, COUNT(budget) OVER (PARTITION BY dept_name, location ORDER BY budget, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_count_budget FROM cleaned WHERE budget IS NULL;
